<?php require 'config/bootstrap.php';auth();if(me()['role']!=='penjual')exit('Hanya penjual');$s=$pdo->prepare('SELECT * FROM toko WHERE user_id=?');$s->execute([me()['id']]);$t=$s->fetch();if(!$t){$pdo->prepare('INSERT INTO toko(user_id,nama_toko,deskripsi) VALUES(?,?,?)')->execute([me()['id'],me()['nama'],'']);$t=['nama_toko'=>me()['nama'],'deskripsi'=>''];}if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$n=trim($_POST['nama_toko']??'');if($n){$pdo->prepare('UPDATE toko SET nama_toko=?,deskripsi=? WHERE user_id=?')->execute([$n,trim($_POST['deskripsi']??''),me()['id']]);flash('Toko disimpan');header('Location: profile.php');exit;}$err='Nama toko wajib diisi';}headpage('Atur toko');?><div class="panel p-4"><h1>Atur toko</h1><?php if(isset($err)):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Nama toko</label><input class="form-control mb-3" name="nama_toko" value="<?=e($t['nama_toko'])?>" required><label>Deskripsi</label><textarea class="form-control mb-3" name="deskripsi"><?=e($t['deskripsi'])?></textarea><button class="btn btn-green">Simpan</button></form></div><?php footpage();